args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?youngerFilm ?youngerFilmLabel ?youngerDirector ?youngerBirth ?otherDirector ?otherBirth WHERE {
  {
    dbr:Chased_by_the_Dogs dbo:director ?dir1 .
    dbr:The_Demise_of_Herman_Durer dbo:director ?dir2 .
    OPTIONAL { ?dir1 dbo:birthDate ?bd1 . }
    OPTIONAL { ?dir1 dbp:birth_date ?bd1p . }
    OPTIONAL { ?dir2 dbo:birthDate ?bd2 . }
    OPTIONAL { ?dir2 dbp:birth_date ?bd2p . }
    BIND(COALESCE(?bd1, ?bd1p) AS ?b1)
    BIND(COALESCE(?bd2, ?bd2p) AS ?b2)
    FILTER(BOUND(?b1) && BOUND(?b2) && ?b1 > ?b2)
    BIND(dbr:Chased_by_the_Dogs AS ?youngerFilm)
    BIND(?dir1 AS ?youngerDirector)
    BIND(?b1 AS ?youngerBirth)
    BIND(?dir2 AS ?otherDirector)
    BIND(?b2 AS ?otherBirth)
    OPTIONAL { dbr:Chased_by_the_Dogs rdfs:label ?youngerFilmLabel . FILTER(lang(?youngerFilmLabel)='en') }
  }
  UNION
  {
    dbr:Chased_by_the_Dogs dbo:director ?dir1 .
    dbr:The_Demise_of_Herman_Durer dbo:director ?dir2 .
    OPTIONAL { ?dir1 dbo:birthDate ?bd1 . }
    OPTIONAL { ?dir1 dbp:birth_date ?bd1p . }
    OPTIONAL { ?dir2 dbo:birthDate ?bd2 . }
    OPTIONAL { ?dir2 dbp:birth_date ?bd2p . }
    BIND(COALESCE(?bd1, ?bd1p) AS ?b1)
    BIND(COALESCE(?bd2, ?bd2p) AS ?b2)
    FILTER(BOUND(?b1) && BOUND(?b2) && ?b2 > ?b1)
    BIND(dbr:The_Demise_of_Herman_Durer AS ?youngerFilm)
    BIND(?dir2 AS ?youngerDirector)
    BIND(?b2 AS ?youngerBirth)
    BIND(?dir1 AS ?otherDirector)
    BIND(?b1 AS ?otherBirth)
    OPTIONAL { dbr:The_Demise_of_Herman_Durer rdfs:label ?youngerFilmLabel . FILTER(lang(?youngerFilmLabel)='en') }
  }
}
LIMIT 10

